const { describe, it } = require('node:test');
const assert = require('node:assert');
const Packet = require('../lib/packet');
const Deserializer = require('../deserializer');

//single flow packet
const VYOS_PACKET1 = '';
//multi flow packet
const VYOS_PACKET2 = '';
//needs readCounterRecords
const VYOS_PACKET3 = '';

const u32 = (...values) => Buffer.concat(values.map(value => {
    const b = Buffer.alloc(4);
    b.writeUInt32BE(value);
    return b;
}));
const record = (format, data) => Buffer.concat([u32(format, data.length), data]);
const sample = (format, body) => Buffer.concat([u32(format, body.length), body]);
const enterprise = (number, format) => number * 4096 + format;

// A raw packet header record of an Ethernet frame carrying an IPv4 TCP packet
const rawHeader = () => {
    const frame = Buffer.alloc(56);
    frame.writeUInt16BE(0x0800, 12);
    frame.writeUInt8(0x45, 14);
    frame.writeUInt8(6, 23);
    return record(1, Buffer.concat([u32(1, 1500, 4, frame.length), frame]));
};
const flowSample = (...records) => sample(1, Buffer.concat([u32(1, 3, 4096, 4096, 0, 3, 5, records.length), ...records]));
const counterSample = (...records) => sample(2, Buffer.concat([u32(1, 3, records.length), ...records]));
// A datagram from agent 10.200.10.252
const datagram = (...samples) => Buffer.concat([u32(5, 1, 0x0AC80AFC, 0, 1, 1000, samples.length), ...samples]);

describe('Packet', () => {
    it('decodes a VyOS flow sample', () => {
        const p = new Packet(Buffer.from(VYOS_PACKET1, 'hex'));

        assert.strictEqual(p.DataSets.length, 1);
        assert.strictEqual(p.DataSets[0].input, 3);
        assert.strictEqual(p.DataSets[0].samplingRate, 500);
        assert.deepStrictEqual(p.DataSets[0].records.map(r => r.type), ['extendedSwitch', 'tag', 'raw']);
    });

    it('decodes a VyOS datagram of 7 flow samples', () => {
        const p = new Packet(Buffer.from(VYOS_PACKET2, 'hex'));

        assert.strictEqual(p.DataSets.length, 7);
        p.DataSets.forEach(flow => {
            assert.strictEqual(flow.format, 1);
            assert.strictEqual(flow.records.length, 3);
        });
    });

    it('decodes a VyOS counter sample before its flow samples', () => {
        const p = new Packet(Buffer.from(VYOS_PACKET3, 'hex'));

        assert.strictEqual(p.header.Samples, 8);
        assert.strictEqual(p.DataSets.length, 8);
        assert.strictEqual(p.DataSets[0].format, 2);
        assert.deepStrictEqual(p.DataSets[0].counters.map(c => c.format), [1]);
    });

    it('keeps a counter record it does not know and reads on', () => {
        const p = new Packet(datagram(
            counterSample(record(2003, Buffer.alloc(12)), record(enterprise(4413, 1), Buffer.alloc(8)), record(1001, Buffer.alloc(28))),
            flowSample(rawHeader())
        ));

        const [counters, flow] = p.DataSets;
        assert.deepStrictEqual(counters.counters.map(c => [c.type, c.enterprise, c.format, c.length]),
            [['unknown', 0, 2003, 12], ['unknown', 4413, 1, 8], [undefined, undefined, 1001, 28]]);
        assert.strictEqual(flow.records[0].type, 'raw');
        assert.strictEqual(flow.records[0].header.length, 56);
    });

    it('keeps a flow record it does not know and reads the next one', () => {
        const p = new Packet(datagram(flowSample(record(1013, Buffer.alloc(16)), rawHeader())));

        const [unknown, raw] = p.DataSets[0].records;
        assert.deepStrictEqual([unknown.type, unknown.enterprise, unknown.format, unknown.data.length], ['unknown', 0, 1013, 16]);
        assert.strictEqual(raw.type, 'raw');
        assert.strictEqual(raw.header.readUInt16BE(12), 0x0800);
    });

    it('keeps a sample type it does not know, standard or enterprise, and reads the next sample', () => {
        const p = new Packet(datagram(sample(5, Buffer.alloc(36)), sample(enterprise(4413, 1), Buffer.alloc(20)), flowSample(rawHeader())));

        assert.deepStrictEqual(p.DataSets.map(s => [s.type, s.enterprise, s.format, s.length]),
            [['unknown', 0, 5, 36], ['unknown', 4413, 1, 20], [undefined, 0, 1, p.DataSets[2].length]]);
        assert.strictEqual(p.DataSets[2].records[0].type, 'raw');
        assert.strictEqual(p.DataSets[2].samplingRate, 4096);
    });
});

describe('Deserializer', () => {
    it('resolves a datagram with records it does not know', async () => {
        const p = await new Deserializer().deserialize(datagram(counterSample(record(2003, Buffer.alloc(12))), flowSample(rawHeader())));

        assert.strictEqual(p.header.ipAddress, '10.200.10.252');
        assert.strictEqual(p.DataSets[1].records[0].type, 'raw');
    });

    it('rejects a version other than 5', async () => {
        const v4 = datagram();
        v4.writeUInt32BE(4, 0);

        await assert.rejects(new Deserializer().deserialize(v4), { message: 'Version unsupported! 4' });
    });
});
